57			}
58			right, err := buildCondition(call.Args[1], pc)
59			if err != nil {
60				return nil, err
61			}
62			return &LogicalCondition{
63				Operator: LogicalAnd,
64				Left:     left,
65				Right:    right,
66			}, nil
67		case "_||_":
68			if len(call.Args) != 2 {
69				return nil, errors.New("logical OR expects two arguments")
70			}
71			left, err := buildCondition(call.Args[0], pc)
72			if err != nil {
73				return nil, err
74			}
75			right, err := buildCondition(call.Args[1], pc)
76			if err != nil {
77				return nil, err
78			}
79			return &LogicalCondition{
80				Operator: LogicalOr,
81				Left:     left,
82				Right:    right,
83			}, nil
84		case "!_":
85			if len(call.Args) != 1 {
86				return nil, errors.New("logical NOT expects one argument")
87			}
88			child, err := buildCondition(call.Args[0], pc)
89			if err != nil {
90				return nil, err
91			}
92			return &NotCondition{Expr: child}, nil
93		case "_==_", "_!=_", "_<_", "_>_", "_<=_", "_>=_":
94			return buildComparisonCondition(call, pc)
